1170 |         public async Task<Response<List<AbilityChangeHistoryResp>>> GetAbilityChangeHistory(string userId, JobPosition jobPosition)
1171 |         {
1172 |             var histories = await UnitWork.Find<JobAbilityChangeHistory>(
1173 |                 x => x.UserId == userId && x.JobPosition == (int)jobPosition)
1174 |                 .OrderBy(x => x.CreateTime)
1175 |                 .ToListAsync();
1176 | 
1177 |             if (!histories.Any())
1178 |                 return new Response<List<AbilityChangeHistoryResp>> { Code = 200, Message = "操作成功", Result = new List<AbilityChangeHistoryResp>() };
1179 | 
1180 |             var historyIds = histories.Select(x => x.Id).ToList();
1181 |             var allItems = await UnitWork.Find<JobAbilityChangeHistoryItem>(
1182 |                 x => historyIds.Contains(x.ChangeHistoryId))
1183 |                 .ToListAsync();
1184 | 
1185 |             var itemsGrouped = allItems.GroupBy(x => x.ChangeHistoryId)
1186 |                 .ToDictionary(g => g.Key, g => g.OrderBy(i => i.AbilityCode).ToList());
1187 | 
1188 |             var result = new List<AbilityChangeHistoryResp>();
1189 |             List<JobAbilityChangeHistoryItem> previousItems = null;
1190 |             // 技术员 A/B/C 为初/中/高级，互斥存在
1191 |             var techLevelCodes = new HashSet<string> { "A", "B", "C" };
1192 |             bool isTechnician = jobPosition == JobPosition.Technician;
1193 | 
1194 |             foreach (var history in histories)
1195 |             {
1196 |                 itemsGrouped.TryGetValue(history.Id, out var currentItems);
1197 |                 currentItems = currentItems ?? new List<JobAbilityChangeHistoryItem>();
1198 | 
1199 |                 string changeContent;
1200 |                 if (previousItems == null)
1201 |                 {
1202 |                     // 第一条记录：显示初始状态
1203 |                     changeContent = string.Join(", ", currentItems.Select(
1204 |                         item => $"{item.AbilityRemark}：{item.AbilityCode}{item.AbilityValue}"));
1205 |                 }
1206 |                 else if (isTechnician)
1207 |                 {
1208 |                     // 技术员特殊处理
1209 |                     var changes = new List<string>();
1210 |                     var curLevel = currentItems.Find(i => techLevelCodes.Contains(i.AbilityCode));
1211 |                     var prevLevel = previousItems.Find(i => techLevelCodes.Contains(i.AbilityCode));
1212 | 
1213 |                     if (curLevel != null && prevLevel != null)
1214 |                     {
1215 |                         if (curLevel.AbilityCode != prevLevel.AbilityCode)
1216 |                         {
1217 |                             // 级别变化：初级 -> 高级
1218 |                             changes.Add($"{prevLevel.AbilityRemark} 变更为 {curLevel.AbilityRemark}，{prevLevel.AbilityCode}{prevLevel.AbilityValue} -> {curLevel.AbilityCode}{curLevel.AbilityValue}");
1219 |                         }
1220 |                         else if (curLevel.AbilityValue != prevLevel.AbilityValue)
1221 |                         {
1222 |                             // 同级等级变化
1223 |                             changes.Add($"{curLevel.AbilityRemark}：{curLevel.AbilityCode}{prevLevel.AbilityValue} -> {curLevel.AbilityCode}{curLevel.AbilityValue}");
1224 |                         }
1225 |                     }
1226 |                     else if (curLevel != null && prevLevel == null)
1227 |                     {
1228 |                         changes.Add($"{curLevel.AbilityRemark}：{curLevel.AbilityCode}{curLevel.AbilityValue}");
1229 |                     }
1230 | 
1231 |                     // U(院校技能) 按通用逻辑处理
1232 |                     foreach (var item in currentItems.Where(i => !techLevelCodes.Contains(i.AbilityCode)))
1233 |                     {
1234 |                         var prevItem = previousItems.Find(p => p.AbilityCode == item.AbilityCode);
1235 |                         if (prevItem == null || prevItem.AbilityValue != item.AbilityValue)
1236 |                         {
1237 |                             var oldValue = prevItem != null
1238 |                                 ? $"{item.AbilityCode}{prevItem.AbilityValue}"
1239 |                                 : "无";
1240 |                             changes.Add($"{item.AbilityRemark}变更：{oldValue} -> {item.AbilityCode}{item.AbilityValue}");
1241 |                         }
1242 |                     }
1243 |                     changeContent = changes.Any() ? string.Join(", ", changes) : "无变更";
1244 |                 }
1245 |                 else
1246 |                 {
1247 |                     // 销售员/研发工程师：通用逻辑
1248 |                     var changes = new List<string>();
1249 |                     foreach (var item in currentItems)
1250 |                     {
1251 |                         var prevItem = previousItems.Find(p => p.AbilityCode == item.AbilityCode);
1252 |                         if (prevItem == null || prevItem.AbilityValue != item.AbilityValue)
1253 |                         {
1254 |                             var oldValue = prevItem != null
1255 |                                 ? $"{item.AbilityCode}{prevItem.AbilityValue}"
1256 |                                 : "无";
1257 |                             changes.Add($"{item.AbilityRemark}变更：{oldValue} -> {item.AbilityCode}{item.AbilityValue}");
1258 |                         }
1259 |                     }
1260 |                     changeContent = changes.Any() ? string.Join(", ", changes) : "无变更";
1261 |                 }
1262 | 
1263 |                 result.Add(new AbilityChangeHistoryResp
1264 |                 {
1265 |                     CreateId = history.CreateId,
1266 |                     ChangeContent = changeContent,
1267 |                     Reason = history.Reason,
1268 |                     CreateName = history.CreateName,
1269 |                     CreateTime = history.CreateTime
1270 |                 });
1271 | 
1272 |                 previousItems = currentItems;
1273 |             }
1274 | 
1275 |             result.Reverse();
1276 |             return new Response<List<AbilityChangeHistoryResp>> { Code = 200, Message = "操作成功", Result = result };
1277 |         }
